import time
import numpy as np
import networkx as nx
from scipy.optimize import minimize

from qiskit import QuantumCircuit
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator


def parse_partition(partition, nodes):
    """Parses reference partition into two sets of node labels."""
    if partition is None:
        return set(nodes[: len(nodes) // 2]), set(nodes[len(nodes) // 2 :])
    if isinstance(partition, dict):
        g0 = {u for u in nodes if partition.get(u) == 0}
        g1 = {u for u in nodes if partition.get(u) != 0}
        return g0, g1
    if isinstance(partition, (list, tuple)) and len(partition) == 2:
        return set(partition[0]), set(partition[1])
    return set(nodes[: len(nodes) // 2]), set(nodes[len(nodes) // 2 :])


def get_cut_size(G, group0, group1):
    """Calculates the number of edges crossing between group0 and group1."""
    return sum(
        1
        for u, v in G.edges()
        if (u in group0 and v in group1) or (u in group1 and v in group0)
    )


def compute_normalized_cut(G, group0, group1):
    """Computes the normalized cut score: cut/vol(A) + cut/vol(B)."""
    if not group0 or not group1:
        return 0.0
    vol0 = sum(G.degree(node) for node in group0)
    vol1 = sum(G.degree(node) for node in group1)
    if vol0 == 0 or vol1 == 0:
        return 0.0
    cut = get_cut_size(G, group0, group1)
    return float(cut / vol0 + cut / vol1)


def compute_modularity(G, group0, group1):
    """Computes Newman modularity for two communities."""
    if not group0 or not group1:
        return 0.0
    try:
        return float(nx.community.modularity(G, [group0, group1]))
    except Exception:
        return 0.0


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=2,
    lambda_balance=0.6,
    lambda_cut=4.0,
    opt_shots=512,
    final_shots=2048,
    maxiter=60,
    n_repro_runs=3,
    seed=42,
):
    """Solves graph partitioning for radio channel assignment minimizing intra-group interference

    subject to balance constraints using QAOA.
    """
    start_time = time.perf_counter()

    # Build networkx graph
    G = nx.Graph()
    G.add_nodes_from(graph_vertices)
    G.add_edges_from(graph_edges)
    nodes = list(graph_vertices)
    N = len(nodes)

    # Construct Ising Hamiltonian coupling matrix J_ij
    # Cost H(z) = -lambda_cut * Cut(z) + lambda_balance * (sum z_i)^2
    J = np.zeros((N, N))
    for i in range(N):
        for j in range(i + 1, N):
            u, v = nodes[i], nodes[j]
            if G.has_edge(u, v):
                J[i, j] = (lambda_cut / 2.0) + 2.0 * lambda_balance
            else:
                J[i, j] = 2.0 * lambda_balance

    # Parametric QAOA Circuit construction
    qc = QuantumCircuit(N)
    qc.h(range(N))

    gammas = ParameterVector("gamma", p_layers)
    betas = ParameterVector("beta", p_layers)

    for l in range(p_layers):
        # Problem Unitary
        for i in range(N):
            for j in range(i + 1, N):
                if J[i, j] != 0:
                    qc.rzz(2 * gammas[l] * J[i, j], i, j)
        # Mixer Unitary
        for i in range(N):
            qc.rx(2 * betas[l], i)

    qc.measure_all()
    backend = AerSimulator()

    def evaluate_cost(z_vec):
        g0 = {nodes[k] for k in range(N) if z_vec[k] == 1}
        g1 = {nodes[k] for k in range(N) if z_vec[k] == -1}
        c_val = get_cut_size(G, g0, g1)
        bal_penalty = (len(g0) - len(g1)) ** 2
        return -lambda_cut * c_val + lambda_balance * bal_penalty

    run_cuts = []
    best_overall_cost = float("inf")
    best_overall_cut = -1
    best_overall_partition = (set(nodes), set())

    for run_idx in range(n_repro_runs):
        run_seed = seed + run_idx * 100
        rng = np.random.default_rng(run_seed)
        init_params = rng.uniform(0.0, np.pi / 2, 2 * p_layers)

        def objective_func(params):
            param_dict = {
                gammas[i]: params[i] for i in range(p_layers)
            }
            param_dict.update(
                {betas[i]: params[p_layers + i] for i in range(p_layers)}
            )
            bound_qc = qc.assign_parameters(param_dict)
            res = backend.run(
                bound_qc, shots=opt_shots, seed_simulator=run_seed
            ).result()
            counts = res.get_counts()

            total_cost = 0.0
            for bitstr, cnt in counts.items():
                z = np.array(
                    [1 if b == "0" else -1 for b in reversed(bitstr)]
                )
                total_cost += evaluate_cost(z) * cnt
            return total_cost / opt_shots

        res_opt = minimize(
            objective_func,
            init_params,
            method="COBYLA",
            options={"maxiter": maxiter},
        )

        opt_params = res_opt.x
        param_dict = {gammas[i]: opt_params[i] for i in range(p_layers)}
        param_dict.update(
            {betas[i]: opt_params[p_layers + i] for i in range(p_layers)}
        )
        final_qc = qc.assign_parameters(param_dict)

        final_res = backend.run(
            final_qc, shots=final_shots, seed_simulator=run_seed
        ).result()
        counts = final_res.get_counts()

        best_cost_run = float("inf")
        best_cut_run = -1
        best_part_run = None

        for bitstr, cnt in counts.items():
            z = np.array([1 if b == "0" else -1 for b in reversed(bitstr)])
            g0 = {nodes[k] for k in range(N) if z[k] == 1}
            g1 = {nodes[k] for k in range(N) if z[k] == -1}
            c_val = get_cut_size(G, g0, g1)
            cost_val = evaluate_cost(z)

            if cost_val < best_cost_run:
                best_cost_run = cost_val
                best_cut_run = c_val
                best_part_run = (g0, g1)

        run_cuts.append(best_cut_run)

        if best_cost_run < best_overall_cost:
            best_overall_cost = best_cost_run
            best_overall_cut = best_cut_run
            best_overall_partition = best_part_run

    elapsed_time = time.perf_counter() - start_time

    group0, group1 = best_overall_partition

    # Metric evaluation
    modularity_score = compute_modularity(G, group0, group1)
    normalized_cut_score = compute_normalized_cut(G, group0, group1)
    balance_constraint_score = float((len(group0) - len(group1)) ** 2)

    ref_g0, ref_g1 = parse_partition(known_reference_partition, nodes)
    ref_cut = get_cut_size(G, ref_g0, ref_g1)

    if ref_cut > 0:
        approximation_ratio = float(best_overall_cut / ref_cut)
    else:
        approximation_ratio = 1.0

    max_cut_found = max(run_cuts) if run_cuts else 1
    reproducibility = float(
        sum(1 for c in run_cuts if c == max_cut_found) / n_repro_runs
    )

    return {
        "modularity_score": modularity_score,
        "normalized_cut_score": normalized_cut_score,
        "balance_constraint_score": balance_constraint_score,
        "approximation_ratio": approximation_ratio,
        "runtime": elapsed_time,
        "reproducibility": reproducibility,
    }

